import json,subprocess,hashlib
from pathlib import Path
p=Path('~/Developer/tjs1882-3175/windows-arm-attempt08')
source=p/'monero-fcmp/external/randomx/src/jit_compiler_a64_static.S'
assert hashlib.sha256(source.read_bytes()).hexdigest()=='f31e68e4325bb5be41eaeaf63975bf760ff158be80f0ce800e43497e9d9f693f'
new=bytes.fromhex('')
assert hashlib.sha256(new).hexdigest()=='158033e0e3c552b201581ea1c427c4989abc65a462b05b5c72d9faf34c9438a1'
out=p/'assembler-correction-fixture09';out.mkdir(mode=0o700)
corrected=out/'corrected.S';corrected.write_bytes(new)
compilers=[Path('/Library/Developer/CommandLineTools/usr/bin/clang'),Path('/Applications/Xcode.app/Contents/Developer/Toolchains/XcodeDefault.xctoolchain/usr/bin/clang')]
clang=next(str(c) for c in compilers if c.exists())
results=[]
for name,target in [('ELF','aarch64-linux-gnu'),('MACHO','arm64-apple-darwin')]:
 outputs=[]
 for f in [source,corrected]:
  r=subprocess.run([clang,'-target',target,'-E','-P','-I',str(source.parent),str(f)],capture_output=True,timeout=20)
  assert r.returncode==0
  outputs.append(r.stdout)
 assert outputs[0]==outputs[1]
 results.append({'target':name,'preprocessed_bytes_identical':True,'sha256':hashlib.sha256(outputs[0]).hexdigest()})
for name,f in [('original',source),('corrected',corrected)]:
 obj=out/(name+'.obj')
 r=subprocess.run([clang,'-target','aarch64-w64-windows-gnu','-march=armv8-a+crypto','-I',str(source.parent),'-c',str(f),'-o',str(obj)],capture_output=True,timeout=20)
 row={'target':'WINDOWS_COFF','source':name,'exit':r.returncode,'unknown_directive':b'unknown directive' in r.stderr}
 if name=='original':assert r.returncode!=0 and b'unknown directive' in r.stderr
 else:
  assert r.returncode==0,r.stderr.decode()
  b=obj.read_bytes();assert int.from_bytes(b[:2],'little')==0xaa64
  row.update(machine=0xaa64,object_bytes=len(b),object_sha256=hashlib.sha256(b).hexdigest())
 results.append(row)
result={'schema':'meownero-arm08-coff-assembler-correction/1','result':'PASS_OLD_FAILS_NEW_COFF_ASSEMBLES_OTHER_PLATFORMS_IDENTICAL','old_source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'new_source_sha256':hashlib.sha256(new).hexdigest(),'compiler_sha256':hashlib.sha256(Path(clang).read_bytes()).hexdigest(),'compiler_version':subprocess.run([clang,'--version'],capture_output=True,text=True,timeout=10).stdout.splitlines()[0],'cases':results,'full_build':'UNTESTED','native_Windows_runtime':'UNTESTED'}
(out/'result.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))
